#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using LastRail.Battle;
using LastRail.Presentation.MissionShell;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
using TMPro;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
namespace LastRail.Tests.EditMode {
 public class EquipmentMultishotControllerTests {
  static JObject Example()=>JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/en17-presentation-example-20261016.json"));
  static JObject Actual(string name)=>(JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/MiraEquipped-20261016/PresentationSource/server-packets.json"))["packets"]["grown"]["presentations"][name];
  static EquipmentMultishotModel Model(JObject p)=>EquipmentMultishotModel.Read(p,p,BDirectAttackInput.Digest(p),(string)p["accountId"],(string)p["runId"]);
  static object Controller(string account,string run){var t=typeof(BMiraFirstTrialContext).Assembly.GetType("LastRail.Presentation.MissionShell.EquipmentMultishotController");Assert.That(t,Is.Not.Null,"Presentation binding controller missing");return Activator.CreateInstance(t,account,run);}
  static object Call(object c,string name,params object[] args){var m=c.GetType().GetMethods().SingleOrDefault(x=>x.Name==name&&x.GetParameters().Length==args.Length);Assert.That(m,Is.Not.Null,name);try{return m.Invoke(c,args);}catch(TargetInvocationException e){throw e.InnerException;}}
  static Task Refresh(object c,string basis,Func<CancellationToken,Task<EquipmentMultishotModel>> f)=>(Task)Call(c,"RefreshAsync",basis,f);
  [Test]public async Task ActualCurrentFailureKeepsIndependentFrozenOriginal(){var e=Example();var c=Controller((string)e["current"]["accountId"],(string)e["current"]["runId"]);JObject frame=null;Call(c,"Bind",(Action<JObject>)(v=>frame=v),(Action)(()=>{}));await Refresh(c,"ORIGINAL_LOCAL_TRIAL_START",_=>Task.FromResult(Model((JObject)e["departure"])));var frozen=frame["departure"].DeepClone();await Refresh(c,"CURRENT_VERIFIED_EQUIPMENT",_=>Task.FromException<EquipmentMultishotModel>(new InvalidOperationException("read failure")));Assert.That(JToken.DeepEquals(frame["departure"],frozen),Is.True);Assert.That((string)frame["currentNotice"],Is.Not.Empty);Call(c,"Unbind");}
  [Test]public async Task RebindAndUnbindIgnoreOldAsyncReadAndClearOnlyOwnedView(){var e=Example();var c=Controller("a",(string)e["current"]["runId"]);int oldFrames=0,newFrames=0,cleared=0;Call(c,"Bind",(Action<JObject>)(_=>oldFrames++),(Action)(()=>cleared++));var pending=new TaskCompletionSource<EquipmentMultishotModel>();CancellationToken token=default;var task=Refresh(c,"CURRENT_VERIFIED_EQUIPMENT",t=>{token=t;return pending.Task;});Call(c,"Bind",(Action<JObject>)(_=>newFrames++),(Action)(()=>cleared++));int count=newFrames;pending.SetResult(Model((JObject)e["current"]));await task;Assert.That(token.IsCancellationRequested,Is.True);Assert.That(newFrames,Is.EqualTo(count));Assert.That(cleared,Is.EqualTo(1));Call(c,"Unbind");Assert.That(cleared,Is.EqualTo(2));}
  [Test]public async Task ActualHighestDuplicateAndStoredStatesStayIndependent(){var highest=(JObject)Actual("highest")["current"];var c=Controller("a",(string)highest["runId"]);JObject frame=null;Call(c,"Bind",(Action<JObject>)(v=>frame=v),(Action)(()=>{}));await Refresh(c,"CURRENT_VERIFIED_EQUIPMENT",_=>Task.FromResult(Model(highest)));Assert.That((string)frame["current"]["slots"][0]["statusLabel"],Is.EqualTo("더 높은 효과 적용 중"));Assert.That((string)frame["current"]["slots"][1]["statusLabel"],Is.EqualTo("적용 중"));Assert.That((string)frame["current"]["slots"][2]["statusLabel"],Is.EqualTo("동일 효과 중복 · 1개 적용"));await Refresh(c,"CURRENT_VERIFIED_STORED_ITEM",_=>Task.FromResult(Model(Actual("stored"))));Assert.That((string)frame["stored"]["slots"][0]["statusLabel"],Is.EqualTo("장착 시 적용 여부 결정"));Assert.That((string)frame["current"]["summary"],Does.Contain("25%"));Call(c,"Unbind");}
  [TestCase("CURRENT_VERIFIED_EQUIPMENT")][TestCase("CURRENT_VERIFIED_STORED_ITEM")]
  public async Task SuccessfulReadThenFailureInvalidatesOnlyThatBasis(string basis){var highest=(JObject)Actual("highest")["current"];var c=Controller("a",(string)highest["runId"]);JObject frame=null;Call(c,"Bind",(Action<JObject>)(v=>frame=v),(Action)(()=>{}));await Refresh(c,"ORIGINAL_LOCAL_TRIAL_START",_=>Task.FromResult(Model((JObject)Actual("one")["departure"])));var frozen=frame["departure"].DeepClone();await Refresh(c,basis,_=>Task.FromResult(Model(basis=="CURRENT_VERIFIED_EQUIPMENT"?highest:Actual("stored"))));string key=basis=="CURRENT_VERIFIED_EQUIPMENT"?"current":"stored";Assert.That(frame[key].Type,Is.EqualTo(JTokenType.Object));await Refresh(c,basis,_=>Task.FromException<EquipmentMultishotModel>(new InvalidOperationException("changed ledger/unavailable")));Assert.That(frame[key].Type,Is.EqualTo(JTokenType.Null),"Unverified cached equipment cannot remain current/applied");Assert.That((string)frame[key+"Notice"],Is.Not.Empty);Assert.That(JToken.DeepEquals(frame["departure"],frozen),Is.True);Call(c,"Unbind");}
  [Test]public async Task StoredFailureIsVisibleInExistingPopup(){var p=Actual("stored");var font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/_LASTRAIL/UI/Fonts/Pretendard/TMP/Pretendard-Regular SDF.asset");var canvas=new GameObject("EN17StoredErrorQA",typeof(RectTransform),typeof(Canvas));var pages=LobbyDestinationPages.Create(canvas.transform,font,()=>{});var c=Controller("a",(string)p["runId"]);try{pages.Open(LobbyPage.Operators,true);Call(c,"Bind",pages);await Refresh(c,"CURRENT_VERIFIED_STORED_ITEM",_=>Task.FromResult(Model(p)));await Refresh(c,"CURRENT_VERIFIED_STORED_ITEM",_=>Task.FromException<EquipmentMultishotModel>(new InvalidOperationException("no longer stored")));var label=pages.GetComponentsInChildren<TMP_Text>().SingleOrDefault(t=>t.name=="StoredCardNotice");Assert.That(label,Is.Not.Null,"Stored read failure must be visible");Assert.That(label.text,Is.Not.Empty);Assert.That(pages.GetComponentsInChildren<TMP_Text>().Any(t=>t.name=="StoredCoefficient"),Is.False);}finally{Call(c,"Unbind");UnityEngine.Object.DestroyImmediate(canvas);}}
  [Test]public async Task CooperativeCancellationCannotMutateLiveUnbindEnumeration(){var e=Example();var c=Controller("a",(string)e["current"]["runId"]);Call(c,"Bind",(Action<JObject>)(_=>{}),(Action)(()=>{}));var pending=new TaskCompletionSource<EquipmentMultishotModel>();var task=Refresh(c,"CURRENT_VERIFIED_EQUIPMENT",token=>{token.Register(()=>pending.TrySetCanceled(token));return pending.Task;});Assert.DoesNotThrow(()=>Call(c,"Unbind"));await task;}
  [Test]public async Task ExistingPopupReceivesRealSourceAndIndependentNumbersThenReleasesBinding(){var e=Example();var p=(JObject)e["departure"];var font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/_LASTRAIL/UI/Fonts/Pretendard/TMP/Pretendard-Regular SDF.asset");Assert.That(font,Is.Not.Null);var canvas=new GameObject("EN17ExistingPopupQA",typeof(RectTransform),typeof(Canvas));canvas.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;var pages=LobbyDestinationPages.Create(canvas.transform,font,()=>{});var c=Controller("a",(string)p["runId"]);
   try{pages.Open(LobbyPage.Operators,true);Call(c,"Bind",pages);await Refresh(c,"ORIGINAL_LOCAL_TRIAL_START",_=>Task.FromResult(Model(p)));var texts=pages.GetComponentsInChildren<TMP_Text>();Assert.That(texts.Single(t=>t.name=="departureCurrentStar0").text,Is.EqualTo("장비 ★2"));Assert.That(texts.Single(t=>t.name=="departureAppliedStar0").text,Is.EqualTo("시술 당시 ★1"));Assert.That(texts.Single(t=>t.name=="departureCoefficient0").text,Is.EqualTo("추가 피해15%"));pages.GetComponentsInChildren<Button>().Single(b=>b.name=="CloseEquipmentMultishot").onClick.Invoke();Assert.That(pages.GetComponentsInChildren<Transform>().Any(t=>t.name=="EquipmentMultishotDetails"),Is.False);Call(c,"Unbind");}
   finally{UnityEngine.Object.DestroyImmediate(canvas);}
  }
 }
}
#endif
